automatically_repaired_code:
content = note_content['content']
lines = content.split('\n')
songs = []

for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if 'RELEASED_AT' in line:
        parts = line.split('RELEASED_AT')
        song_info = parts[0].strip()
        release_info = parts[1].strip()
        if 'TODO' in release_info:
            # Extract song title and artists
            song_title, artists = song_info.split(' BY ')
            songs.append({
                'title': song_title,
                'artists': artists.split(', '),
                'release_month': 'TODO'
            })
        else:
            # Extract song title and artists
            song_title, artists = song_info.split(' BY ')
            release_month = release_info.split('/')[0]
            songs.append({
                'title': song_title,
                'artists': artists.split(', '),
                'release_month': release_month
            })

print(songs)

